    'CHN': 'China',
    'IND': 'India',
    'IDN': 'Indonesia',
    'MEX': 'Mexico',
    'ZAF': 'South Africa',
    'TUR': 'Turkey'
}

answer = {
    "country": country_names[max_country]
}

print(answer)"}
